function drawMap(){const info=mapCanvasInfo();if(!info)return;const {ctx,w,h}=info;ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle=document.body.classList.contains('light')?'#e7eeee':'#050b0d';ctx.fillRect(0,0,w,h);const g=mapGeometry(info);if(!g)return;const layer=id=>$(id)?.checked!==false;if(layer('layerMap')){ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(mapImage,g.ox,g.oy,g.m.width*g.scale,g.m.height*g.scale);ctx.restore()}if(layer('layerGrid'))drawGridLayer(ctx,g,info);if(layer('layerGlobalCostmap'))drawCostmapLayer(ctx,globalCostmapImage,obj('global_costmap_meta'),g,.78);if(layer('layerLocalCostmap'))drawCostmapLayer(ctx,localCostmapImage,obj('local_costmap_meta'),g,.88);const css=getComputedStyle(document.body);function pathDraw(key,color,width){const data=obj(key),pts=data.points||[],frame=data.frame_id||'map';if(pts.length<2)return;ctx.save();ctx.strokeStyle=css.getPropertyValue(color);ctx.lineWidth=width*info.dpr;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();let started=false;pts.forEach(p=>{const mp=framePointToMap(frame,+p[0],+p[1]);if(!mp)return;const [x,y]=g.trans(mp.x,mp.y);started?ctx.lineTo(x,y):(ctx.moveTo(x,y),started=true)});if(started)ctx.stroke();ctx.restore()}function mppiDraw(){const arr=obj('mppi_trajectories').trajectories||[];if(!arr.length)return;for(const trj of arr){const pts=trj.points||[],frame=trj.frame_id||'odom';if(!pts.length)continue;ctx.save();const col=trj.optimal?css.getPropertyValue('--amber'):css.getPropertyValue('--cyan');ctx.strokeStyle=col;ctx.fillStyle=col;ctx.globalAlpha=trj.optimal?.96:.24;if(trj.optimal){ctx.lineWidth=3*info.dpr;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();let started=false;for(const p of pts){const mp=framePointToMap(frame,+p[0],+p[1]);if(!mp)continue;const [x,y]=g.trans(mp.x,mp.y);started?ctx.lineTo(x,y):(ctx.moveTo(x,y),started=true)}if(started)ctx.stroke()}else{for(let pi=0;pi<pts.length;pi+=Math.max(1,Math.floor(pts.length/26))){const mp=framePointToMap(frame,+pts[pi][0],+pts[pi][1]);if(!mp)continue;const [x,y]=g.trans(mp.x,mp.y);ctx.beginPath();ctx.arc(x,y,1.35*info.dpr,0,Math.PI*2);ctx.fill()}}ctx.restore()}}if(layer('layerGlobalPath'))pathDraw('nav_path','--blue',2.5);if(layer('layerLocalPath'))pathDraw('local_path','--cyan',2.5);if(layer('layerMppi'))mppiDraw();const goal=mapView.draft&&Number.isFinite(+mapView.draft.x)?mapView.draft:obj('goal_pose');if(layer('layerGoal')&&Number.isFinite(+goal.x)){const [x,y]=g.trans(+goal.x,+goal.y);drawPoseArrow(ctx,x,y,+goal.yaw||0,css.getPropertyValue('--red'),info,7)}if(mapView.initialDraft&&Number.isFinite(+mapView.initialDraft.x)){const [ix,iy]=g.trans(+mapView.initialDraft.x,+mapView.initialDraft.y);drawPoseArrow(ctx,ix,iy,+mapView.initialDraft.yaw||0,css.getPropertyValue('--violet'),info,6)}const pose=obj('ekf_global');if(layer('layerRobot')&&Number.isFinite(+pose.x)){const [x,y]=g.trans(+pose.x,+pose.y),yaw=+pose.yaw||0,len=15*info.dpr;ctx.save();ctx.translate(x,y);ctx.rotate(-yaw);ctx.fillStyle=css.getPropertyValue('--green');ctx.strokeStyle='#03110c';ctx.lineWidth=1.5*info.dpr;ctx.beginPath();ctx.moveTo(len,0);ctx.lineTo(-len*.72,len*.58);ctx.lineTo(-len*.45,0);ctx.lineTo(-len*.72,-len*.58);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore()}setText('mapZoomLabel',Math.round(mapView.zoom*100)+'%')}
