async function vescCmd(command,silent=false){return post('/api/esc/vesc/command',{command},silent)}
function selectedVescMotor(){return +($('vescMotor')?.value||1)===2?2:1}
function renderVescTool(){
  const live=obj('vesc_tool_telemetry');
  if(+live.motor===1||+live.motor===2)vescTelemetryByMotor[+live.motor]={...live};
  const active=bool(raw('vesc_maintenance_active')),transport=bool(raw('connected.vesc_transport')),tool=obj('vesc_tool_status'),tcpClient=tool.tcp_client===true,motor=selectedVescMotor(),runtime=obj('foc_telemetry');
  let t=vescTelemetryByMotor[motor]||{};
  if(!active){const r=motor===1?runtime.left:runtime.right;if(r&&typeof r==='object')t={motor,...r}}
  const panel=q('.vesc-tool-panel');if(panel)panel.classList.toggle('maintenance',active);
  const chip=$('vescToolModeChip');if(chip){chip.classList.remove('waiting','bad');chip.textContent=active?'MAINTENANCE':'RUNTIME';if(active)chip.classList.add('waiting')}
  setText('vescTransportState',transport?'ONLINE':'WAIT');setText('vescAuthority',tcpClient?'VESC TOOL TCP':active?'WEB MAINTENANCE':'RUNTIME');
  setText('vescTcpState',tool.tcp_server===false?'OFF':`127.0.0.1:${tool.tcp_port||65102}`);setText('vescTcpDetail',tcpClient?'CLIENT CONNECTED • Web controls locked':'single-client localhost proxy');
  setText('vescVbus',fmt(t.vbus_v,2)+' V');setText('vescRpm',fmt(t.rpm,0));setText('vescPosition',fmt(t.position_deg,2)+'°');setText('vescDuty',fmt(t.duty,3));
  setText('vescIq',fmt(t.iq_a,2)+' A');setText('vescId',fmt(t.id_a,2)+' A');setText('vescMotorCurrent',fmt(t.current_motor_a,2)+' A');setText('vescInputCurrent',fmt(t.current_in_a,2)+' A');setText('vescTemp',fmt(t.temp_mos_c,1)+' °C');setText('vescFault',Number.isFinite(+t.fault)?String(+t.fault):'--');
  setText('vescToolStatus',pretty(obj('vesc_tool_status')));setText('vescRawReply',pretty(obj('vesc_raw_reply')));
  const ids=['vescSendSetpoint','vescSendZero','vescDetectHall','vescDetectEncoder','vescSendTerminal','vescAlive','vescSendRaw','vescReboot','vescReadFw','vescReadValues','vescReadMcconf','vescReadAppconf'];
  ids.forEach(id=>{if($(id))$(id).disabled=!active||tcpClient});if($('vescEnterMaintenance'))$('vescEnterMaintenance').disabled=active;if($('vescExitMaintenance'))$('vescExitMaintenance').disabled=!active;
}
