  setText('ackScaleOperational',Number.isFinite(op)?`±${fmt(Math.abs(op),1)}°`:'±30°');setText('ackScaleErpmPerMps',Number.isFinite(cmdScale)?`${fmt(cmdScale,3)} eRPM/(m/s)`:'--');
  const st=obj('vesc_steering_state');setText('ackScaleEncoderSpan',Number.isFinite(+st.measured_span)?`${st.measured_span} / ${st.safe_span??'--'} counts`:'--');setText('ackScaleEncoderRaw',Number.isFinite(+st.raw_encoder)?`${st.raw_encoder} / ${Number.isFinite(+st.pos360)?fmt(Math.max(0,Math.min(360,+st.pos360)),1):'--'}°`:'--');
  const fill=(id,v)=>{const e=$(id);if(e&&document.activeElement!==e&&Number.isFinite(v))e.value=String(v)};fill('ackScaleWheelRadius',wr);fill('ackScalePolePairs',pp);fill('ackScaleGear',gear);fill('ackScaleDriveScale',driveScale);fill('ackScaleLeftLimit',pl);fill('ackScaleRightLimit',pr);fill('ackScaleOperationalLimit',op);
  const target=deg(raw('esc_steer_target')),actual=deg(raw('esc_steer_actual')),vescPos=deg(raw('esc_steer_protocol_cmd'));
