function renderTop(){const ros=obj('server').ros===true;setText('rosStatus',ros?'ONLINE':'WAIT');$('rosDot').style.background=ros?'var(--green)':'var(--amber)';const mot=bool(raw('system.motion_ready'));setText('motionStatus',mot?'READY':'LOCKED');$('motionDot').style.background=mot?'var(--green)':'var(--amber)';const e=bool(raw('system.estop'));setText('estopStatus',e?'ACTIVE':'CLEAR');$('estopPill').classList.toggle('active',e);setText('serverClock',new Date().toLocaleTimeString('id-ID'))}
function render(){renderTop();switch(activePage){case'overview':renderOverview();break;case'navigation':renderNavigation();break;case'perception':renderPerception();break;case'sensors':renderSensors();break;case'esc':case'esc-status':renderEsc();break;case'esc-ackermann':renderAckermannScaling();break;case'calibration':renderCalibration();break;case'tuning':renderTuning();break;case'reports':renderReports();break;case'diagnostics':renderDiagnostics();break;case'experiments':renderLabWorkbench();break;default:break}}
