async function saveTuningField(i,automatic=false){
  const p=tuningFieldsFor(selectedExperiment)[i],el=$(`tuneField-${i}`);if(!p||!el||el.readOnly||el.disabled)return;
  let value=p.kind==='bool'?el.checked:el.value;
  if(p.kind==='int')value=parseInt(value,10);if(p.kind==='float')value=parseFloat(value);
  if(p.kind==='list'){try{const text=String(value).trim();value=text.startsWith('[')?JSON.parse(text):text.split(',').map(v=>Number(v.trim())).filter(Number.isFinite);if(!Array.isArray(value)||!value.length)throw new Error('empty')}catch(_){return toast('List tidak valid. Pakai [0,2,3] atau 0,2,3',true)}}
  if((p.kind==='int'||p.kind==='float')&&!Number.isFinite(value))return toast('Nilai numerik tidak valid',true);
  const btn=q(`.param-save[data-field-index="${i}"]`),badge=$(`tuneRuntime-${i}`);
  if(!p.yamlFileKey){localRunValues[`${currentExp}:${selectedExperiment.id}:${p.key||p.label}`]=value;if(btn){btn.textContent='SET';btn.classList.add('saved');setTimeout(()=>btn.classList.remove('saved'),900)}if(!automatic)toast('Nilai run/ground truth disimpan untuk sesi browser');return}
  if(btn){btn.disabled=true;btn.textContent='APPLYING'}if(badge){badge.textContent='YAML SAVE';badge.className='runtime-badge pending'}
  try{
    const r=await fetch('/api/config/set',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_key:p.yamlFileKey,path:p.yamlPath,value})}),j=await r.json();if(!r.ok)throw new Error(j.message||`HTTP ${r.status}`);
    if(j.config?.files)configs=j.config.files;
    const st=j.runtime_apply?.status||'YAML_SAVED',match=j.runtime_match===true;
    const label=match?'RUNTIME MATCH':st==='PENDING_STATIONARY'?'PENDING STOP':st==='NEXT_START'?'NEXT START':st==='NO_RUNTIME_TARGET'?'YAML ONLY':st==='RUNTIME_MISMATCH'?'MISMATCH':st;
    if(badge){badge.textContent=label;badge.className='runtime-badge '+(match?'active':st==='RUNTIME_MISMATCH'?'error':'pending')}
    if(btn){btn.textContent=match?'ACTIVE':st==='PENDING_STATIONARY'?'PENDING':'SAVED';btn.classList.toggle('saved',match)}
    toast(`${p.label||p.yamlPath}: ${label}${j.runtime_apply?.message?' • '+j.runtime_apply.message:''}`,st==='RUNTIME_MISMATCH');
    renderCalibration();renderTuning();
    setTimeout(()=>{if(btn){btn.disabled=false;btn.textContent='APPLY';btn.classList.remove('saved')}},1600)
  }catch(e){if(btn){btn.disabled=false;btn.textContent='RETRY'}if(badge){badge.textContent='ERROR';badge.className='runtime-badge error'}toast('YAML/runtime apply gagal: '+e.message,true)}
}
async function resetSelectedExperimentYaml(){
  if(currentExp!=='navigation'||!selectedExperiment)return toast('Reset baseline ini khusus tahap Navigasi.',true);
  if(recordStartedMs)return toast('STOP recording dulu sebelum reset parameter.',true);
  const all=tuningFieldsFor(selectedExperiment).filter(p=>p.yamlFileKey&&p.kind!=='yaml_readonly'&&!p.locked&&baselineConfigValue(p.yamlFileKey,p.yamlPath)!==undefined),seen=new Set(),items=[];
  for(const p of all){const key=`${p.yamlFileKey}:${p.yamlPath}`;if(seen.has(key))continue;seen.add(key);const cur=configValue(p.yamlFileKey,p.yamlPath),base=baselineConfigValue(p.yamlFileKey,p.yamlPath);if(JSON.stringify(cur)!==JSON.stringify(base))items.push(p)}
  if(!items.length)return toast(`${displayExperimentId(selectedExperiment)} sudah sama dengan baseline awal.`);
  confirmModal('Reset YAML tahap ini',`Kembalikan ${items.length} parameter ${displayExperimentId(selectedExperiment)} ke baseline awal? Sistem membuat batch backup sebelum perubahan, tetap membuat .web.bak per parameter, lalu me-restart setiap node terdampak maksimal satu kali saat kendaraan diam.`,async()=>{
    const btn=$('resetExperimentYaml');if(btn){btn.disabled=true;btn.textContent='RESETTING...'}
    try{
      const payload={items:items.map(p=>({file_key:p.yamlFileKey,path:p.yamlPath}))},r=await fetch('/api/config/reset-batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),j=await r.json();
      if(!r.ok)throw new Error(j.message||`HTTP ${r.status}`);if(j.config?.files)configs=j.config.files;await loadConfig();renderTuningFields();renderCalibration();renderTuning();
      const st=j.runtime_apply?.status||'YAML_RESET',match=j.runtime_match===true,label=match?'RUNTIME MATCH':st==='PENDING_STATIONARY'?'MENUNGGU KENDARAAN DIAM':st==='NEXT_START'?'AKTIF SAAT START BERIKUTNYA':st==='NO_RUNTIME_TARGET'?'YAML RESET':st;
      toast(`Reset baseline ${displayExperimentId(selectedExperiment)}: ${items.length} parameter • ${label}`,st==='RUNTIME_MISMATCH')
    }catch(e){if(btn){btn.disabled=false;btn.textContent=`↶ Reset ${items.length} Parameter ke Baseline`}toast('Batch reset YAML gagal: '+e.message,true)}
  })
}
