function downloadExperimentGraphPng(index){
  const src=$(`experimentChart-${index}`),status=$(`chartDataStatus-${index}`)?.textContent||'';
  if(!src||!selectedExperiment||status.includes('WAITING'))return toast('Grafik belum memiliki data hasil recording',true);
  const g=selectedExperiment.graphs?.[index]||{},caption=selectedExperiment.graphCaptions?.[index]||`Grafik ${index+1}`,
        xLabel=g.xLabel||(g.type==='scatter'?g.xSeries:'Time [s]'),yLabel=g.yLabel||(g.type==='scatter'?g.ySeries:'Value'),
        out=document.createElement('canvas');
  out.width=1600;out.height=720;
  // Report export is always light/white like the Matplotlib backend. Re-render
  // the live chart once with a white chart background, copy it, then restore
  // the operator theme immediately. Series colors remain unchanged.
  const body=document.body,oldInline=body.style.getPropertyValue('--chart-bg');
  body.style.setProperty('--chart-bg','#ffffff');drawExperimentChart(index);
  const ctx=out.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,out.width,out.height);
  ctx.fillStyle='#111827';ctx.font='700 28px system-ui';ctx.fillText(`${displayExperimentId(selectedExperiment)} • ${caption}`,52,52);
  ctx.fillStyle='#4b5563';ctx.font='18px system-ui';ctx.fillText(`Variation: ${$('runVariation').value} • Condition: ${$('runCondition').value} • ${new Date().toLocaleString('id-ID')}`,52,84);
  ctx.drawImage(src,50,112,1500,500);
  if(oldInline)body.style.setProperty('--chart-bg',oldInline);else body.style.removeProperty('--chart-bg');drawExperimentChart(index);
  ctx.fillStyle='#374151';ctx.font='18px system-ui';ctx.fillText(`X: ${xLabel||'Time [s]'}`,52,642);ctx.textAlign='right';ctx.fillText(`Y: ${yLabel||'Value'}`,1548,642);ctx.textAlign='left';
  const legend=($(`chartLegend-${index}`)?.innerText||'').replace(/\s+/g,' ').trim();if(legend){ctx.fillStyle='#1f2937';ctx.font='15px system-ui';ctx.fillText(legend.slice(0,180),52,680)}
  out.toBlob(blob=>{if(!blob)return toast('Gagal membuat PNG grafik',true);const safe=String(selectedExperiment.id).replace(/[^a-z0-9._-]+/gi,'_'),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${safe}_graph_${index+1}_${stamp()}.png`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Grafik ${index+1} PNG didownload`)},'image/png')
}
function drawChartEmpty(ctx,w,h,msg){ctx.fillStyle='rgba(140,165,170,.7)';ctx.font=`13px ui-monospace`;ctx.textAlign='center';ctx.fillText(msg,w/2,h/2);ctx.textAlign='left';setText('chartDataStatus','WAITING DATA');setText('chartLegend','Source akan aktif otomatis ketika ROS publish.')}
function metricStats(path){const a=metricHistory.get(path)||[];if(!a.length)return null;const v=a.map(p=>p.v),mean=v.reduce((x,y)=>x+y,0)/v.length,rmse=Math.sqrt(v.reduce((x,y)=>x+y*y,0)/v.length),sorted=[...v].sort((a,b)=>a-b),p95=sorted[Math.max(0,Math.ceil(.95*sorted.length)-1)];return {last:v.at(-1),mean,rmse,min:Math.min(...v),max:Math.max(...v),p95,std:Math.sqrt(v.reduce((x,y)=>x+(y-mean)**2,0)/v.length),count:v.length}}
function primaryMetricPath(){return Object.values(selectedExperiment?.liveSeries||{})[0]}
function scatterStatsForGraph(g){if(g<0)return null;const pts=scatterHistory.get(`${currentExp}:${selectedExperiment.id}:${g}`)||[];if(pts.length<2)return null;const mx=pts.reduce((a,p)=>a+p.x,0)/pts.length,my=pts.reduce((a,p)=>a+p.y,0)/pts.length,dx=pts.map(p=>p.x-mx),dy=pts.map(p=>p.y-my),stdx=Math.sqrt(dx.reduce((a,v)=>a+v*v,0)/pts.length),stdy=Math.sqrt(dy.reduce((a,v)=>a+v*v,0)/pts.length),rad=pts.map((p,i)=>Math.hypot(dx[i],dy[i])).sort((a,b)=>a-b),rms=Math.sqrt(rad.reduce((a,v)=>a+v*v,0)/rad.length),r95=rad[Math.max(0,Math.ceil(.95*rad.length)-1)];return {stdx,stdy,rms,r95,count:pts.length,mx,my}}
function currentScatterStats(){return scatterStatsForGraph((selectedExperiment?.graphs||[]).findIndex(x=>x?.type==='scatter'))}
function parameterSnapshotEntries(){return tuningFieldsFor(selectedExperiment).filter(p=>p.yamlFileKey).map(p=>{const v=configValue(p.yamlFileKey,p.yamlPath),text=Array.isArray(v)||v&&typeof v==='object'?JSON.stringify(v):String(v??'--');return {label:p.label||p.key||p.yamlPath,key:p.key||p.label||p.yamlPath,value:text,file:p.yamlFileKey,group:p.group||'Parameter / YAML'}})}
function trialInputsForSelected(){const out={};for(const p of tuningFieldsFor(selectedExperiment).filter(p=>!p.yamlFileKey)){const key=p.key||p.label;const saved=localRunValues[`${currentExp}:${selectedExperiment.id}:${key}`];let v=saved!==undefined?saved:p.placeholder;if(p.kind==='float'||p.kind==='int'){const n=Number(v);v=Number.isFinite(n)?n:v}else if(p.kind==='bool')v=v===true||String(v).toLowerCase()==='true';out[key]=v}return out}
function driveErpmPerMps(){const r=+configValue('esc','esc_ackermann.ros__parameters.drive_wheel_radius_m')||.145,pp=+configValue('esc','esc_ackermann.ros__parameters.drive_motor_pole_pairs')||15,g=+configValue('esc','esc_ackermann.ros__parameters.drive_gear_ratio')||1;return 60*g*pp/(2*Math.PI*r)}
function automaticTrialId(){return currentExp==='navigation'&&['N2.1','N3.1','N3.2'].includes(String(selectedExperiment?.id||''))}
function trialGuideFor(x){
  const id=String(x?.id||''),fields=tuningFieldsFor(x).filter(p=>!p.yamlFileKey),vars=fields.map(p=>`${p.label||p.key}: ${localRunValues[`${currentExp}:${id}:${p.key||p.label}`]??p.placeholder??'set sesuai run'}`);
  if(id==='N2.1'){const per=driveErpmPerMps(),vmax=+configValue('vehicle','vehicle.ros__parameters.max_forward_speed_mps')||.5,lim=Math.floor(per*vmax);return {status:'GNSS STRICT + AREA LURUS',steps:[`Gunakan lintasan datar/lurus, GNSS fix sehat, steering sudah center dan area bebas minimal 10–20 m.`,`Set RPM/eRPM RIGHT. Rekomendasi awal: 100, 200, 300, 400 eRPM; hard auto-run saat ini ≤ ${lim} eRPM (${vmax.toFixed(2)} m/s).`,`Klik START. Sistem reset grafik ke t=0, center steering, ramp drive, lalu merekam RPM, GNSS speed/X/Y, ESC raw/calibrated speed dan IMU diagnostic speed.`,`Jalankan 10–20 s dengan bagian steady minimal 5 s, lalu STOP. Rata-rata dihitung dari bagian tengah run agar ramp start/stop tidak mendominasi.`,`Ulangi minimal 3 trial dan ≥2 level RPM berbeda, lalu tekan Hitung + Apply Scale Optimal.`],estimate:`Konversi nominal: 1 m/s ≈ ${per.toFixed(1)} eRPM. 1000 eRPM ≈ ${(1000/per).toFixed(2)} m/s sehingga saat ini melewati envelope ${vmax.toFixed(2)} m/s.`,criteria:'≥3 trial valid dan ≥2 level RPM; scale kandidat konsisten setelah outlier rejection; GNSS fix sehat; fault ESC=0.'}}
  if(id==='N3.1')return {status:'SCALE VX FIX • STRAIGHT',steps:['Pastikan N2.1 scale sudah diterapkan dan kendaraan berada pada lintasan lurus/datar.','Steering otomatis dikunci 0° saat START. Variasikan RPM, misalnya 100/200/300/400 eRPM sesuai envelope aktif.','Bandingkan gyro-Z, yaw IMU, Yahboom magnetic heading, NEO3 IST8310 heading, dan GNSS COG.','Gunakan run 10–20 s; ulangi ≥3 kali per speed bila menentukan center final.','Nilai correction candidate hanya rekomendasi; center steering final ditetapkan setelah arah drift konsisten pada beberapa speed.'],estimate:'Target lurus: mean gyro-Z mendekati 0 rad/s dan perubahan heading antar sensor kecil/berarah konsisten.',criteria:'Drift yaw/lateral harus konsisten kecil pada ≥3 repeat dan beberapa speed; dual magnetometer/GNSS tidak menunjukkan sign konflik.'}
  if(id==='N3.2')return {status:'CLEAR TURNING AREA',steps:['Pastikan N2.1 dan N3.1 sudah selesai. Gunakan area luas tanpa obstacle.','Pilih steering, misalnya ±10°, ±20°, lalu ±30° operational limit; pilih RPM rendah lebih dulu.','START akan mengunci steering sesuai variasi lalu meramp drive. Rekam steering, GNSS/ESC speed, gyro, dual magnetometer, COG, dan lintasan X-Y.','Untuk radius yang baik, usahakan arc ≥180° jika area memungkinkan; STOP sebelum mendekati batas area.','Bandingkan radius dari V_GNSS/gyro dengan model Ackermann dan effective-wheelbase candidate.'],estimate:'Awali 100–250 eRPM untuk ±20…30°; naikkan hanya setelah radius dan clearance aman.',criteria:'Radius GNSS/gyro dan model Ackermann konsisten antar repeat; yaw sign benar; effective-wheelbase candidate stabil dan tidak fault.'}
  return {status:'OFAT / REPEATABLE',steps:[`Ubah satu variabel utama per run (OFAT). ${vars.length?'Variabel run: '+vars.join(' • '):'Gunakan variasi yang didefinisikan tahap ini.'}`,'Pastikan source pada panel LIVE/READY sebelum START.','START selalu mereset grafik/time axis ke t=0; pertahankan kondisi steady yang cukup panjang.','STOP menyimpan raw CSV, YAML recap, XLSX, dan PNG grafik. Ulangi minimal 3 run untuk repeatability.'],estimate:'Gunakan nilai default sebagai baseline; ubah bertahap dan jangan melewati safety ceiling yang dikunci.'}
}
function renderTrialGuide(){const p=$('trialGuidePanel');if(!p||!selectedExperiment)return;const g=trialGuideFor(selectedExperiment);setText('trialGuideSafety',g.status);setText('trialGuideTitle',`${displayExperimentId(selectedExperiment)} • Procedure & Recommended Variation`);$('trialGuideBody').innerHTML=`<ol>${g.steps.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ol><div class="tuning-note"><b>Estimasi:</b> ${escapeHtml(g.estimate||'')}</div>`}

