const OBCAL_DISTANCES=[1,2,3,4,5];
const OBCAL_TYPES={human:{label:'Human',classId:0,short:'H'},motorcycle:{label:'Motorcycle',classId:3,short:'M'}};
const OBCAL_ORIENTATIONS=[
  {id:'front',label:'Depan',short:'D'},
  {id:'rear',label:'Belakang',short:'B'},
  {id:'left',label:'Samping Kiri',short:'Ki'},
  {id:'right',label:'Samping Kanan',short:'Ka'}
];
const OBCAL_TOTAL=OBCAL_DISTANCES.length*Object.keys(OBCAL_TYPES).length*OBCAL_ORIENTATIONS.length;
const OBCAL_STORAGE='adv-obstacle-calibration-v2-orientation';
let obstacleCal={samples:[]};
try{const saved=JSON.parse(localStorage.getItem(OBCAL_STORAGE)||'null');if(saved&&Array.isArray(saved.samples))obstacleCal=saved}catch(_){ }
function saveObstacleCalLocal(){localStorage.setItem(OBCAL_STORAGE,JSON.stringify(obstacleCal))}
function obcalOrientationName(id){return OBCAL_ORIENTATIONS.find(o=>o.id===id)?.label||id}
function obcalSample(distance,type,orientation){return obstacleCal.samples.find(s=>+s.distance===+distance&&s.type===type&&s.orientation===orientation)}
function obcalDistanceCount(distance){let n=0;for(const type of Object.keys(OBCAL_TYPES))for(const o of OBCAL_ORIENTATIONS)if(obcalSample(distance,type,o.id))n++;return n}
function obcalDistanceComplete(distance){return obcalDistanceCount(distance)===Object.keys(OBCAL_TYPES).length*OBCAL_ORIENTATIONS.length}
function obcalNextCombination(distance){for(const type of ['human','motorcycle'])for(const o of OBCAL_ORIENTATIONS)if(!obcalSample(distance,type,o.id))return{type,orientation:o.id};return null}
function obcalCompletedCount(){let n=0;for(const d of OBCAL_DISTANCES)n+=obcalDistanceCount(d);return n}
function obcalFirstIncomplete(){return OBCAL_DISTANCES.find(d=>!obcalDistanceComplete(d))??5}
function obcalSelectedClassId(){return OBCAL_TYPES[$('obcalType')?.value||'human']?.classId??0}
function obcalMinConfidence(){const sd=obj('semantic_detections');const v=+sd.score_threshold;return Number.isFinite(v)?Math.max(.10,v):.20}
function obcalCandidateState(){
  if(!bool(raw('connected.camera')))return{ready:false,reason:'CAMERA OFF'};
  if(raw('camera_healthy')===false)return{ready:false,reason:'CAMERA UNHEALTHY'};
  if(!channelFresh('semantic_detections',3))return{ready:false,reason:'WAIT SEMANTIC'};
  const rd=obj('semantic_detections'),arr=Array.isArray(rd.detections)?rd.detections:[],cls=obcalSelectedClassId(),minConf=obcalMinConfidence();
  const same=arr.filter(d=>+d.class_id===cls&&Number.isFinite(+d.score));
  if(!same.length)return{ready:false,reason:'CLASS NOT FOUND',minConf,rejected:0};
  const confident=same.filter(d=>+d.score>=minConf);
  if(!confident.length)return{ready:false,reason:`LOW CONF < ${minConf.toFixed(2)}`,minConf,rejected:same.length};
  const centered=confident.filter(d=>Number.isFinite(+d.center_x_fraction)&&Math.abs(+d.center_x_fraction-.5)<=.18);
  if(!centered.length)return{ready:false,reason:'CENTER OBJECT',minConf,rejected:same.length};
  centered.sort((a,b)=>(+b.score||0)-(+a.score||0));
  const d=centered[0],dist=+$('obcalDistance')?.value||1;
  if(!Number.isFinite(+d.bottom_u_px)||!Number.isFinite(+d.bottom_v_px))return{ready:false,reason:'NO BBOX FOOT',minConf,d};
  if(dist>=3&&d.bottom_clipped)return{ready:false,reason:'GROUND CONTACT CLIPPED',minConf,d};
  if(dist>=3&&!Number.isFinite(+d.raw_forward_m))return{ready:false,reason:'METRIC X INVALID',minConf,d};
  return{ready:true,reason:'CAPTURE READY',minConf,d,rejected:Math.max(0,same.length-1)};
}
function obcalDetectionForSelection(){return obcalCandidateState().d||null}
function obcalFit(type){const pts=obstacleCal.samples.filter(s=>s.type===type&&+s.distance>=3&&!s.bottom_clipped&&Number.isFinite(+s.raw_forward_m)).map(s=>({x:+s.raw_forward_m,y:+s.distance}));if(pts.length<2)return null;const xm=pts.reduce((a,p)=>a+p.x,0)/pts.length,ym=pts.reduce((a,p)=>a+p.y,0)/pts.length;let num=0,den=0;for(const p of pts){num+=(p.x-xm)*(p.y-ym);den+=(p.x-xm)*(p.x-xm)}if(Math.abs(den)<1e-9)return null;const scale=num/den,bias=ym-scale*xm;let ssr=0,sst=0,ae=0,rawAe=0,se=0,maxe=0;for(const p of pts){const pred=scale*p.x+bias,e=pred-p.y;ssr+=e*e;sst+=(p.y-ym)*(p.y-ym);ae+=Math.abs(e);rawAe+=Math.abs(p.x-p.y);se+=e*e;maxe=Math.max(maxe,Math.abs(e))}return{type,n:pts.length,scale,bias,mae:ae/pts.length,rawMae:rawAe/pts.length,rmse:Math.sqrt(se/pts.length),maxe,r2:sst>1e-9?1-ssr/sst:1}}
function obcalCalibrated(sample){const fit=obcalFit(sample.type);return fit&&Number.isFinite(+sample.raw_forward_m)?fit.scale*(+sample.raw_forward_m)+fit.bias:null}
function obcalMetricUse(sample){return +sample.distance>=3&&!sample.bottom_clipped&&Number.isFinite(+sample.raw_forward_m)}
function obcalClassName(type){return OBCAL_TYPES[type]?.label||type}
function obcalSortSamples(a,b){const td={human:0,motorcycle:1},od=Object.fromEntries(OBCAL_ORIENTATIONS.map((o,i)=>[o.id,i]));return a.distance-b.distance||(td[a.type]??9)-(td[b.type]??9)||(od[a.orientation]??9)-(od[b.orientation]??9)}
function renderObstacleCalibrationWizard(){
  const w=$('obstacleCalibrationWizard');if(!w||w.hidden)return;
  const distSel=$('obcalDistance'),typeSel=$('obcalType'),oriSel=$('obcalOrientation');
  let current=+distSel.value||obcalFirstIncomplete();
  const first=obcalFirstIncomplete();
  if(!OBCAL_DISTANCES.includes(current)||(obcalDistanceComplete(current)&&current!==first)||current>first)current=first;
  distSel.value=String(current);
  const complete=obcalDistanceComplete(current),nextCombo=obcalNextCombination(current);
  distSel.disabled=complete;
  qa('option',distSel).forEach(o=>{const d=+o.value;o.disabled=obcalDistanceComplete(d)||d>first});
  if(nextCombo){typeSel.value=nextCombo.type;oriSel.value=nextCombo.orientation}
  typeSel.disabled=true;oriSel.disabled=true;
  const candidateState=obcalCandidateState();
  $('obcalCaptureBtn').disabled=complete||!nextCombo||!candidateState.ready;
  $('obcalNextBtn').disabled=!complete||current>=5;
  const rows=OBCAL_DISTANCES.map(d=>{
    const chips=[];
    for(const type of ['human','motorcycle'])for(const o of OBCAL_ORIENTATIONS){const done=!!obcalSample(d,type,o.id);chips.push(`<span class="obcal-mini-chip ${done?'done':'wait'}" title="${escapeHtml(obcalClassName(type)+' / '+o.label)}">${done?'✓':'○'} ${OBCAL_TYPES[type].short}-${o.short}</span>`)}
    const n=obcalDistanceCount(d),locked=n===8,active=d===current;
    return `<div class="obcal-progress-row ${locked?'locked':''} ${active?'active':''}"><b>${d} m</b><div class="obcal-progress-mini">${chips.join('')}</div><span class="obcal-row-count">${n}/8</span><em>${locked?'LOCKED':active?'ACTIVE':'PENDING'}</em></div>`
  }).join('');
  $('obcalProgress').innerHTML=rows;
  const count=obcalCompletedCount(),pct=count/OBCAL_TOTAL*100;
  $('obcalProgressBar').style.width=pct+'%';
  setText('obcalProgressText',`${count} / ${OBCAL_TOTAL} kombinasi selesai`);
  setText('obcalState',`${count} / ${OBCAL_TOTAL}`);
  $('obcalState').className='status-chip '+(count===OBCAL_TOTAL?'':'waiting');
  const body=obstacleCal.samples.slice().sort(obcalSortSamples).map(s=>{const cal=obcalCalibrated(s),err=Number.isFinite(cal)?cal-s.distance:null;return `<tr><td>${(+s.distance).toFixed(1)} m</td><td>${escapeHtml(obcalClassName(s.type))}</td><td>${escapeHtml(obcalOrientationName(s.orientation))}</td><td>${fmt(s.score,2)}</td><td>${fmt(s.bottom_u_px,0)}</td><td>${fmt(s.bottom_v_px,0)}</td><td>${Number.isFinite(+s.raw_forward_m)?fmt(s.raw_forward_m,3):'—'}</td><td>${Number.isFinite(cal)?fmt(cal,3):'—'}</td><td>${Number.isFinite(err)?(err>=0?'+':'')+fmt(err,3):'—'}</td><td>${s.bottom_clipped?'YES':'NO'}</td><td>${obcalMetricUse(s)?'METRIC':'NEAR-FIELD'}</td></tr>`}).join('');
  $('obcalTableBody').innerHTML=body||'<tr><td colspan="11" class="muted">Belum ada sample.</td></tr>';
  const hf=obcalFit('human'),mf=obcalFit('motorcycle'),fits=[hf,mf].filter(Boolean);
  setText('obcalFitSummary',fits.length?fits.map(f=>`${obcalClassName(f.type)} MAE ${f.mae.toFixed(3)} m • n=${f.n}`).join(' | '):'Belum cukup data metric');
  const ready=count===OBCAL_TOTAL&&hf&&mf;
  $('obcalSaveApply').disabled=!ready;
  setText('obcalResultTitle',ready?'READY TO SAVE & APPLY':`WAITING ${OBCAL_TOTAL-count} SAMPLE`);
  setText('obcalResultDetail',ready?`40/40 lengkap • Human a=${hf.scale.toFixed(4)} b=${hf.bias.toFixed(4)} n=${hf.n} • Motor a=${mf.scale.toFixed(4)} b=${mf.bias.toFixed(4)} n=${mf.n} • metric safety validation tetap terpisah.`:'Setiap jarak wajib 8 capture: Human + Motorcycle × Depan/Belakang/Samping Kiri/Samping Kanan.');
  if(complete)setText('obcalRule',`${current} m selesai 8/8 dan terkunci. Klik Next Distance untuk melanjutkan.`);
  else if(nextCombo)setText('obcalRule',`Posisikan ${obcalClassName(nextCombo.type)} orientasi ${obcalOrientationName(nextCombo.orientation)} pada ${current} m, tepat di koridor tengah kamera. Tunggu bbox stabil lalu OK / Capture.`);
  drawObstacleCalibrationChart();renderObstacleCalibrationLive()
}
function renderObstacleCalibrationLive(){const cs=obcalCandidateState(),d=cs.d;setText('obcalLiveStatus',cs.reason);if(!d){setText('obcalDetectedClass','--');setText('obcalDetectedConf','--');setText('obcalDetectedPixel','--');setText('obcalDetectedRaw','--');setText('obcalDetectedCal','--');setText('obcalDetectedClip','--');return}setText('obcalDetectedClass',`${obcalClassName($('obcalType').value)} • ${obcalOrientationName($('obcalOrientation').value)}`);setText('obcalDetectedConf',`${fmt(d.score,3)} / min ${cs.minConf.toFixed(2)}`);setText('obcalDetectedPixel',`${fmt(d.bottom_u_px,0)}, ${fmt(d.bottom_v_px,0)}`);setText('obcalDetectedRaw',Number.isFinite(+d.raw_forward_m)?fmt(d.raw_forward_m,3)+' m':'--');setText('obcalDetectedCal',Number.isFinite(+d.calibrated_forward_m)?fmt(d.calibrated_forward_m,3)+' m':'--');setText('obcalDetectedClip',d.bottom_clipped?'YES':'NO')}
function captureObstacleCalibrationSample(){
  const dist=+$('obcalDistance').value,type=$('obcalType').value,orientation=$('obcalOrientation').value;
  const expected=obcalNextCombination(dist);
  if(!expected)return toast(`${dist} m sudah lengkap 8/8`,true);
  if(type!==expected.type||orientation!==expected.orientation)return toast(`Urutan aktif: ${obcalClassName(expected.type)} / ${obcalOrientationName(expected.orientation)}`,true);
  if(obcalSample(dist,type,orientation))return toast(`${dist} m / ${obcalClassName(type)} / ${obcalOrientationName(orientation)} sudah tersimpan`,true);
  if(!channelFresh('semantic_detections',3))return toast('Semantic detector tidak fresh; tunggu Person/Car/Motor detector aktif',true);
  const cs=obcalCandidateState(),d=cs.d;if(!cs.ready||!d)return toast(`Belum siap capture: ${cs.reason}`,true);
  obstacleCal.samples.push({distance:dist,type,orientation,class_id:OBCAL_TYPES[type].classId,captured_at:new Date().toISOString(),score:+d.score||0,x1:+d.x1,y1:+d.y1,x2:+d.x2,y2:+d.y2,bottom_u_px:+d.bottom_u_px,bottom_v_px:+d.bottom_v_px,bbox_height_fraction:+d.bbox_height_fraction||0,center_x_fraction:+d.center_x_fraction||.5,bottom_clipped:!!d.bottom_clipped,metric_matched:!!d.metric_matched,raw_forward_m:Number.isFinite(+d.raw_forward_m)?+d.raw_forward_m:null,raw_left_m:Number.isFinite(+d.raw_left_m)?+d.raw_left_m:null});
  saveObstacleCalLocal();toast(`${dist} m / ${obcalClassName(type)} / ${obcalOrientationName(orientation)} tersimpan`);renderObstacleCalibrationWizard()
}
function nextObstacleCalibrationDistance(){const current=+$('obcalDistance').value;if(!obcalDistanceComplete(current))return toast(`${current} m belum lengkap: ${obcalDistanceCount(current)}/8`,true);const next=OBCAL_DISTANCES.find(d=>d>current&&!obcalDistanceComplete(d));if(!next)return toast('Semua 40 kombinasi 1–5 m sudah selesai');$('obcalDistance').disabled=false;$('obcalDistance').value=String(next);renderObstacleCalibrationWizard()}
function obstacleCalibrationCsv(){const header=['distance_gt_m','type','orientation','class_id','captured_at','confidence','x1_px','y1_px','x2_px','y2_px','bottom_u_px','bottom_v_px','bbox_height_fraction','bottom_clipped','metric_matched','raw_forward_m','raw_left_m','calibrated_forward_m','error_m','used_for'];const rows=obstacleCal.samples.slice().sort(obcalSortSamples).map(s=>{const c=obcalCalibrated(s),e=Number.isFinite(c)?c-s.distance:null;return[s.distance,s.type,s.orientation,s.class_id,s.captured_at,s.score,s.x1,s.y1,s.x2,s.y2,s.bottom_u_px,s.bottom_v_px,s.bbox_height_fraction,s.bottom_clipped,s.metric_matched,s.raw_forward_m,s.raw_left_m,c,e,obcalMetricUse(s)?'metric_fit':'near_field_reference']});return [header,...rows].map(r=>r.map(csvCell).join(',')).join('\n')}
