function drawObstacleCalibrationChart(){const c=$('obcalChart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height,cs=getComputedStyle(document.documentElement),fg=cs.getPropertyValue('--muted').trim()||'#8ca3a8',grid=cs.getPropertyValue('--border').trim()||'#1b3035',blue=cs.getPropertyValue('--blue').trim()||'#31a8ff',green=cs.getPropertyValue('--green').trim()||'#36e6a1',amber=cs.getPropertyValue('--amber').trim()||'#ffbd59';ctx.clearRect(0,0,w,h);ctx.fillStyle='#050d0f';ctx.fillRect(0,0,w,h);const pad={l:52,r:18,t:20,b:42},x=v=>pad.l+(v/5)*(w-pad.l-pad.r),y=v=>h-pad.b-(v/6)*(h-pad.t-pad.b);ctx.strokeStyle=grid;ctx.lineWidth=1;ctx.fillStyle=fg;ctx.font='12px sans-serif';for(let i=0;i<=5;i++){ctx.beginPath();ctx.moveTo(x(i),pad.t);ctx.lineTo(x(i),h-pad.b);ctx.stroke();ctx.fillText(String(i),x(i)-3,h-pad.b+18)}for(let i=0;i<=6;i++){ctx.beginPath();ctx.moveTo(pad.l,y(i));ctx.lineTo(w-pad.r,y(i));ctx.stroke();ctx.fillText(String(i),pad.l-24,y(i)+4)}ctx.setLineDash([6,5]);ctx.strokeStyle=fg;ctx.beginPath();ctx.moveTo(x(0),y(0));ctx.lineTo(x(5),y(5));ctx.stroke();ctx.setLineDash([]);for(const type of ['human','motorcycle']){const fit=obcalFit(type),col=type==='human'?blue:amber;for(const s of obstacleCal.samples.filter(s=>s.type===type&&Number.isFinite(+s.raw_forward_m))){const oi=OBCAL_ORIENTATIONS.findIndex(o=>o.id===s.orientation),jx=(oi-1.5)*.025;ctx.fillStyle=col;ctx.beginPath();ctx.arc(x(+s.distance+jx),y(+s.raw_forward_m),4,0,Math.PI*2);ctx.fill();if(fit){const cal=fit.scale*(+s.raw_forward_m)+fit.bias;ctx.strokeStyle=green;ctx.strokeRect(x(+s.distance+jx)-3,y(cal)-3,6,6)}}}ctx.fillStyle=fg;ctx.fillText('Actual distance from camera (m)',w/2-80,h-9);ctx.save();ctx.translate(14,h/2+60);ctx.rotate(-Math.PI/2);ctx.fillText('Estimated distance (m)',0,0);ctx.restore()}
